#!/usr/bin/env node
/**
 * Copy generated content into the app's public/ so Vite serves it.
 *
 *   npm run sync:content        (runs automatically before dev and build)
 *
 * The content lives at SEIMAcademy/content/ because it is generated by the Phase 1
 * pipeline and reviewed there. The app needs it under public/ to serve it as static
 * assets, and a static host needs it inside the built bundle. Copying keeps one source of
 * truth and leaves the deployed artifact self-contained.
 *
 * public/content/ is generated and gitignored. Never edit it; regenerate instead.
 */
import { cpSync, existsSync, rmSync, mkdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const SRC = path.resolve(HERE, '..', '..', 'content');
const DEST = path.resolve(HERE, '..', 'public', 'content');

if (!existsSync(SRC)) {
  console.error(`No generated content at ${SRC}.\nRun: node SEIMAcademy/scripts/build-content.mjs`);
  process.exit(1);
}

rmSync(DEST, { recursive: true, force: true });
mkdirSync(path.dirname(DEST), { recursive: true });
for (const entry of ['build-manifest.json', 'lessons', 'exercise-data']) {
  const from = path.join(SRC, entry);
  if (existsSync(from)) cpSync(from, path.join(DEST, entry), { recursive: true });
}
console.log(`synced content -> ${path.relative(process.cwd(), DEST)}`);
